// The now playing bar's text split (NowPlayingBar.x placeText): a page's "title • artists" line, or its title
// alone, parted into the two lines the redesign draws, with the track metadata the player reports deciding
// where a title that holds " • " itself ends. NowPlayingBar.x is generated by Logos and included here so its
// statics are reachable; the player state, the view tree of Spotify's page and the stubs it links against are
// doubles. A failed check exits 1 with its name.
#import <UIKit/UIKit.h>
#import "../harness-fail.h"
#import "Shared/Player/PlayerState.h"

#pragma mark - the player's state, a double

@interface SPTPlayerTrack ()
@property (nonatomic, readwrite) NSString *trackTitle;
@property (nonatomic, readwrite) NSString *artistName;
@end
// Every read of a title is counted: a scan of the player's tracks reads one per track, so the count tells scans apart.
static NSUInteger sg_titleReads;

@implementation SPTPlayerTrack {
    NSString *_trackTitle;
}
- (NSString *)trackTitle {
    sg_titleReads++;
    return _trackTitle;
}
- (void)setTrackTitle:(NSString *)title {
    _trackTitle = title;
}
@end

@interface SPTPlayerState ()
@property (nonatomic, readwrite) SPTPlayerTrack *track;
@property (nonatomic, readwrite) NSArray *future;
@property (nonatomic, readwrite) NSArray *reverse;
@end
@implementation SPTPlayerState
@end

static SPTPlayerState *sg_state;
SPTPlayerState *SGPlayerState(void) { return sg_state; }

#include "NowPlayingBar.gen.m"

#pragma mark - Spotify's page, a double

static SPTPlayerTrack *makeTrack(NSString *title, NSString *artist) {
    SPTPlayerTrack *t = [SPTPlayerTrack new];
    t.trackTitle = title;
    t.artistName = artist;
    return t;
}

// A marquee as Spotify nests it: a view named Encore.MarqueeLabel holding the label that has the text.
static UIView *addMarquee(UIView *unit, NSString *text, BOOL hidden) {
    UIView *view = [[UIView alloc] initWithFrame:CGRectMake(0, 0, 200, 20)];
    view.accessibilityIdentifier = @"Encore.MarqueeLabel";
    view.hidden = hidden;
    UILabel *label = [[UILabel alloc] initWithFrame:view.bounds];
    label.text = text;
    [view addSubview:label];
    [unit addSubview:view];
    return view;
}

// `device`: the page with a device line, whose first marquee is "title • artists" and a later hidden one the
// artists alone (empty when `hiddenArtists` is nil). Without: the title, then the artists in sight.
static UIView *makePage(NSString *line, NSString *hiddenArtists, BOOL device, NSString *shownArtists) {
    UIView *page = [[UIView alloc] initWithFrame:CGRectMake(0, 0, 300, 56)];
    page.accessibilityIdentifier = kPageId;
    UIView *unit = [[UIView alloc] initWithFrame:page.bounds];
    unit.accessibilityIdentifier = kUnitId;
    [page addSubview:unit];
    addMarquee(unit, line, NO);
    if (device) addMarquee(unit, hiddenArtists ?: @"", YES);
    else addMarquee(unit, shownArtists, NO);
    return page;
}

static NSUInteger sg_checks;

static void expect(NSString *name, UIView *page, NSString *title, NSString *artists) {
    placeText(page);
    SGRBarText *text = objc_getAssociatedObject(page, &kTextKey);
    HARNESS_CHECK(text != nil);
    NSString *gotArtists = text.artists.text;
    if (![text.title.text isEqualToString:title] || ![gotArtists isEqualToString:artists]) {
        HARNESS_FAIL(@"%@: title \"%@\" artists \"%@\", wanted \"%@\" \"%@\"", name, text.title.text, gotArtists, title, artists);
    }
    sg_checks++;
}

// The text size is the app's (stubs.m) and the window's traits, which is how UIKit tells a view the size changed.
extern UIContentSizeCategory sg_harnessTextSize;

static void setTextSize(UIWindow *window, UIContentSizeCategory category) {
    sg_harnessTextSize = category;
    window.traitOverrides.preferredContentSizeCategory = category;
    [NSRunLoop.mainRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:0.1]];
}

static SGRBarText *barIn(UIView *host) {
    UIView *page = makePage(@"Stay High • Juice WRLD", @"", YES, nil);
    [host addSubview:page];
    placeText(page);
    return objc_getAssociatedObject(page, &kTextKey);
}

// Both fonts and both frames, as the bar draws them.
static NSString *textLook(SGRBarText *text) {
    return [NSString stringWithFormat:@"title %.1fpt %@, artists %.1fpt %@", text.title.font.pointSize,
            NSStringFromCGRect(text.title.frame), text.artists.font.pointSize, NSStringFromCGRect(text.artists.frame)];
}

// A bar kept across text sizes looks as one made at that size.
static void checkTextSize(void) {
    UIWindow *window = [(id)UIApplication.sharedApplication.delegate window];
    UIView *host = window.rootViewController.view;
    setTextSize(window, UIContentSizeCategorySmall);
    SGRBarText *kept = barIn(host);
    NSString *small = textLook(kept);
    NSString *large = nil;
    for (UIContentSizeCategory category in @[UIContentSizeCategoryLarge, UIContentSizeCategorySmall]) {
        setTextSize(window, category);
        NSString *fresh = textLook(barIn(host)), *now = textLook(kept);
        if (![now isEqualToString:fresh]) HARNESS_FAIL(@"text size %@: a kept bar draws %@, a new one %@", category, now, fresh);
        if (category == UIContentSizeCategoryLarge) large = now;
        sg_checks++;
    }
    if ([small isEqualToString:large]) HARNESS_FAIL(@"same %@ / %@", small, large);
    HARNESS_CHECK([textLook(kept) isEqualToString:small]);
}

static void run(void) {
    SPTPlayerTrack *plain = makeTrack(@"Stay High", @"Juice WRLD"), *dotted = makeTrack(@"Rock • Roll", @"The Band");
    SPTPlayerTrack *shorter = makeTrack(@"Rock", @"Roll Crew");
    sg_state = [SPTPlayerState new];
    sg_state.track = dotted;
    sg_state.future = @[plain, shorter];
    sg_state.reverse = @[makeTrack(@"Back • Again", @"Looper")];

    // A title without the bullet, either layout: what the page always did.
    expect(@"plain, device line", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");
    expect(@"plain, device line and artists", makePage(@"Stay High • Juice WRLD", @"Juice WRLD", YES, nil), @"Stay High", @"Juice WRLD");
    expect(@"plain, no device line", makePage(@"Stay High", nil, NO, @"Juice WRLD"), @"Stay High", @"Juice WRLD");

    // A title with the bullet, the current track.
    expect(@"dotted, device line, hidden artists empty", makePage(@"Rock • Roll • The Band", @"", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"dotted, device line, hidden artists", makePage(@"Rock • Roll • The Band", @"The Band", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"dotted, no device line", makePage(@"Rock • Roll", nil, NO, @"The Band"), @"Rock • Roll", @"The Band");

    // The page of a neighbor in the pager, not the current track: a track to come and one played.
    expect(@"played neighbor", makePage(@"Back • Again • Looper", @"", YES, nil), @"Back • Again", @"Looper");
    expect(@"next neighbor", makePage(@"Rock • Roll Crew", @"", YES, nil), @"Rock", @"Roll Crew");
    expect(@"next neighbor, plain", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");

    // A short title followed by its artist is the head of a neighbor's longer one: the longer title wins.
    sg_state = [SPTPlayerState new];
    sg_state.track = makeTrack(@"Rock", @"Roll");
    sg_state.future = @[makeTrack(@"Rock • Roll", @"The Band")];
    expect(@"collision, neighbor, hidden artists", makePage(@"Rock • Roll • The Band", @"The Band", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"collision, neighbor, hidden artists empty", makePage(@"Rock • Roll • The Band", @"", YES, nil), @"Rock • Roll", @"The Band");
    expect(@"collision, current", makePage(@"Rock", nil, NO, @"Roll"), @"Rock", @"Roll");

    // The same page laid out again, with the same state and line, is not scanned again; a new line or a new state
    // is, and its answer follows.
    sg_state = [SPTPlayerState new];
    sg_state.track = makeTrack(@"Rock • Roll", @"The Band");
    sg_state.future = @[makeTrack(@"Stay High", @"Juice WRLD")];
    UIView *again = makePage(@"Rock • Roll • The Band", @"", YES, nil);
    sg_titleReads = 0;
    expect(@"cache, first layout", again, @"Rock • Roll", @"The Band");
    NSUInteger scan = sg_titleReads;
    HARNESS_CHECK(scan > 0);
    expect(@"cache, same layout again", again, @"Rock • Roll", @"The Band");
    expect(@"cache, same line on another page", makePage(@"Rock • Roll • The Band", @"The Band", YES, nil), @"Rock • Roll", @"The Band");
    if (sg_titleReads != scan) HARNESS_FAIL(@"cache: an unchanged line and state were scanned again (%lu reads, %lu for one scan)", (unsigned long)sg_titleReads, (unsigned long)scan);
    expect(@"cache, new line", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");
    if (sg_titleReads == scan) HARNESS_FAIL(@"cache: a new line was not scanned");
    scan = sg_titleReads;
    SPTPlayerState *next = [SPTPlayerState new];
    next.track = makeTrack(@"Stay High • Juice WRLD", @"Someone");
    sg_state = next;
    expect(@"cache, new state", makePage(@"Stay High • Juice WRLD", nil, NO, @"Someone"), @"Stay High • Juice WRLD", @"Someone");
    HARNESS_CHECK(sg_titleReads > scan);

    // Nothing the player knows: today's reading, the first bullet parts the title.
    sg_state = [SPTPlayerState new];
    expect(@"unknown, device line", makePage(@"Rock • Roll • The Band", @"", YES, nil), @"Rock", @"Roll • The Band");
    expect(@"unknown, no bullet", makePage(@"Unknown Song", nil, NO, @"Somebody"), @"Unknown Song", @"Somebody");
    sg_state = nil;
    expect(@"no state", makePage(@"Stay High • Juice WRLD", @"", YES, nil), @"Stay High", @"Juice WRLD");

    checkTextSize();

    printf("[harness] now-playing-bar: %lu checks passed\n", (unsigned long)sg_checks);
    fflush(stdout);
    exit(0);
}

@interface NowPlayingBarApp : UIResponder <UIApplicationDelegate>
@property (nonatomic, strong) UIWindow *window;
@end
@implementation NowPlayingBarApp
- (BOOL)application:(UIApplication *)application didFinishLaunchingWithOptions:(NSDictionary *)options {
    self.window = [[UIWindow alloc] initWithFrame:CGRectMake(0, 0, 390, 844)];
    self.window.rootViewController = [UIViewController new];
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(0.2 * NSEC_PER_SEC)), dispatch_get_main_queue(), ^{ run(); });
    return YES;
}
@end

int main(int argc, char *argv[]) {
    @autoreleasepool {
        return UIApplicationMain(argc, argv, nil, NSStringFromClass(NowPlayingBarApp.class));
    }
}
